#!/usr/bin/env python3
"""t.py [-d] [-m] in.bimcraft cmdfile_or_cmd...
For each command (a line of a file, or an argument containing '{'), run the original on in.bimcraft
with --cmd LINE --save out.bimcraft; print reply/error and the element diff (-d). With -m, also run
mine and print SAME/DIFF (normalised as cmp.py does)."""
import json, sys, subprocess, tempfile, shutil, os, re

ORIG = '/workspace/executable'
MINE = '/workspace/.claude/worktrees/agent-ae2e58ef39e2084a3/target/release/bimcraft-cli'
GUID = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')


def norm(s):
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}

    def rep(mo):
        g = mo.group(0)
        if g not in m:
            m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    return GUID.sub(rep, s)


def run(exe, src, cmds, extra=()):
    d = tempfile.mkdtemp(prefix='t')
    try:
        shutil.copy(src, os.path.join(d, 'in.bimcraft'))
        args = [exe, 'run', 'in.bimcraft']
        for c in cmds:
            args += ['--cmd', c]
        args += list(extra)
        args += ['--save', 'out.bimcraft']
        p = subprocess.run(args, cwd=d, capture_output=True, text=True, timeout=120)
        out = None
        if os.path.exists(os.path.join(d, 'out.bimcraft')):
            out = open(os.path.join(d, 'out.bimcraft')).read()
        return p.returncode, p.stdout, p.stderr, out
    finally:
        shutil.rmtree(d)


def diff(A, B, full=False):
    ea, eb = A['elements'], B['elements']
    lines = []
    for k in sorted(set(ea) | set(eb), key=int):
        if k not in eb:
            lines.append('- %s %s' % (k, ea[k].get('category')))
        elif k not in ea:
            lines.append('+ %s %s' % (k, json.dumps(eb[k], ensure_ascii=False)[:1500]))
        elif ea[k] != eb[k] or list(ea[k].keys()) != list(eb[k].keys()):
            x, y = ea[k], eb[k]
            if full:
                lines.append('~ %s %s' % (k, json.dumps(y, ensure_ascii=False)[:1500]))
                continue
            diffs = []
            for f in list(y.keys()) + [f for f in x if f not in y]:
                if x.get(f) != y.get(f):
                    diffs.append('%s: %s -> %s' % (f, json.dumps(x.get(f), ensure_ascii=False)[:300], json.dumps(y.get(f), ensure_ascii=False)[:300]))
            if list(x.keys()) != list(y.keys()):
                diffs.append('ORDER %s -> %s' % (list(x.keys()), list(y.keys())))
            lines.append('~ %s %s %s' % (k, y.get('category'), '; '.join(diffs)))
    for k in sorted(set(A) | set(B)):
        if k in ('elements', 'library'):
            continue
        if A.get(k) != B.get(k):
            lines.append('TOP %s %s -> %s' % (k, json.dumps(A.get(k))[:300], json.dumps(B.get(k))[:300]))
    return lines


def main():
    a = sys.argv[1:]
    show_diff = False
    mine = False
    full = False
    pre = []
    while a and a[0].startswith('-'):
        if a[0] == '-d':
            show_diff = True
        elif a[0] == '-D':
            show_diff = True
            full = True
        elif a[0] == '-m':
            mine = True
        elif a[0] == '-p':
            pre.append(a[1])
            a = a[1:]
        a = a[1:]
    src = a[0]
    cmds = []
    for x in a[1:]:
        if '{' in x:
            cmds.append(x)
        else:
            for l in open(x):
                l = l.rstrip('\n')
                if l.strip() and not l.startswith('#'):
                    cmds.append(l)
    A = json.load(open(src))
    nsame = 0
    for c in cmds:
        code, out, err, proj = run(ORIG, src, pre + [c])
        lines = out.splitlines()
        reply = lines[1 + len(pre)] if len(lines) > 1 + len(pre) else ''
        if code != 0:
            res = 'ERR ' + err.strip()
        else:
            res = reply
        tag = ''
        if mine:
            mc, mo, me, mp = run(MINE, src, pre + [c])
            same = (code == mc and norm(out) == norm(mo) and norm(err) == norm(me) and norm(proj or '') == norm(mp or ''))
            tag = 'SAME ' if same else 'DIFF '
            if same:
                nsame += 1
        print('%s%s\n    => %s' % (tag, c, res[:2000]))
        if mine and tag == 'DIFF ':
            mlines = mo.splitlines()
            mreply = mlines[1 + len(pre)] if len(mlines) > 1 + len(pre) else ''
            print('    mine: %s' % (('ERR ' + me.strip()) if mc != 0 else mreply[:2000]))
            if proj and mp and norm(proj) != norm(mp):
                for l in diff(json.loads(proj), json.loads(mp))[:30]:
                    print('      m~ ' + l)
                if norm(proj) != norm(mp) and not diff(json.loads(proj), json.loads(mp)):
                    print('      (file differs in formatting/order)')
        if show_diff and proj:
            for l in diff(A, json.loads(proj), full):
                print('      ' + l)
    if mine:
        print('%d/%d SAME' % (nsame, len(cmds)))


main()

