#!/usr/bin/env python3
"""Helpers for experiments: build a project from commands, run commands on it, summarise."""
import json, subprocess, tempfile, shutil, os, sys

ORIG = '/workspace/executable'
MINE = '/workspace/.claude/worktrees/agent-ae2e58ef39e2084a3/target/release/bimcraft-cli'


def build(cmds, path=None, exe=ORIG):
    d = tempfile.mkdtemp(prefix='ex')
    try:
        open(os.path.join(d, 's.txt'), 'w').write('\n'.join(cmds) + '\n')
        p = subprocess.run([exe, 'run', '--script', 's.txt', '--save', 'o.bimcraft'], cwd=d, capture_output=True, text=True)
        if p.returncode:
            raise RuntimeError(p.stderr)
        data = open(os.path.join(d, 'o.bimcraft')).read()
        if path:
            open(path, 'w').write(data)
        return data
    finally:
        shutil.rmtree(d)


def run(src_text, cmds, exe=ORIG):
    """Returns (ok, reply_or_error, project dict or None)."""
    d = tempfile.mkdtemp(prefix='ex')
    try:
        open(os.path.join(d, 'in.bimcraft'), 'w').write(src_text)
        args = [exe, 'run', 'in.bimcraft']
        for c in cmds:
            args += ['--cmd', c]
        args += ['--save', 'o.bimcraft']
        p = subprocess.run(args, cwd=d, capture_output=True, text=True)
        if p.returncode:
            return False, p.stderr.strip(), None
        lines = p.stdout.splitlines()
        return True, lines[1:1 + len(cmds)], json.loads(open(os.path.join(d, 'o.bimcraft')).read())
    finally:
        shutil.rmtree(d)


def els(proj):
    return {int(k): v for k, v in proj['elements'].items()}


def changes(a_text, proj):
    A = json.loads(a_text)
    out = []
    ea, eb = A['elements'], proj['elements']
    for k in sorted(set(ea) | set(eb), key=int):
        if k not in eb:
            out.append('-%s' % k)
        elif k not in ea:
            out.append('+%s %s' % (k, json.dumps({f: v for f, v in eb[k].items() if f not in ('guid', 'type', 'level', 'top_level', 'view', 'style')})))
        elif ea[k] != eb[k]:
            x, y = ea[k], eb[k]
            ds = []
            for f in list(y.keys()) + [f for f in x if f not in y]:
                if x.get(f) != y.get(f):
                    ds.append('%s=%s' % (f, json.dumps(y.get(f))))
            out.append('~%s %s' % (k, ' '.join(ds)))
    return out

