#!/usr/bin/env python3
"""fz.py kind [n] [seed]: random cases of corner/split/fillet, the original against mine."""
import sys, random, json
sys.path.insert(0, '/tmp/edit-ops')
from exp import build, ORIG, MINE
import t as T

kind = sys.argv[1]
n = int(sys.argv[2]) if len(sys.argv) > 2 else 20
seed = int(sys.argv[3]) if len(sys.argv) > 3 else 1
verbose = '-v' in sys.argv
random.seed(seed)


def rp(lo=-8000, hi=8000, dec=0):
    x = random.uniform(lo, hi)
    return round(x, dec) if dec else float(int(x))


def pt(dec=0):
    return [rp(dec=dec), rp(dec=dec)]


def fmt(p):
    return '[%s, %s]' % (json.dumps(p[0]), json.dumps(p[1]))


def walls_case():
    dec = random.choice([0, 0, 1, 3])
    a0, a1 = pt(dec), pt(dec)
    b0, b1 = pt(dec), pt(dec)
    cmds = ['wall {"points": [%s, %s]}' % (fmt(a0), fmt(a1)), 'wall {"points": [%s, %s]}' % (fmt(b0), fmt(b1))]
    # extra walls joined at ends or on lines
    for _ in range(random.randint(0, 3)):
        base = random.choice([a0, a1, b0, b1])
        jit = random.choice([0, 0, 0.3, 0.9, 1.5])
        p = [base[0] + random.uniform(-jit, jit), base[1] + random.uniform(-jit, jit)]
        q = pt()
        if random.random() < 0.5:
            cmds.append('wall {"points": [%s, %s]}' % (fmt([round(p[0], 3), round(p[1], 3)]), fmt(q)))
        else:
            cmds.append('wall {"points": [%s, %s]}' % (fmt(q), fmt([round(p[0], 3), round(p[1], 3)])))
    for _ in range(random.randint(0, 2)):
        s, e = random.choice([(a0, a1), (b0, b1)])
        u = random.uniform(0.05, 0.95)
        p = [s[0] + (e[0] - s[0]) * u, s[1] + (e[1] - s[1]) * u]
        cmds.append('wall {"points": [%s, %s]}' % (fmt([round(p[0], 3), round(p[1], 3)]), fmt(pt())))
    for _ in range(random.randint(0, 3)):
        s, e = random.choice([(a0, a1), (b0, b1)])
        u = random.uniform(0.1, 0.9)
        p = [s[0] + (e[0] - s[0]) * u, s[1] + (e[1] - s[1]) * u]
        cmds.append('%s {"at": %s}' % (random.choice(['door', 'window']), fmt([round(p[0], 3), round(p[1], 3)])))
    return cmds


def lines_case():
    dec = random.choice([0, 0, 1, 3])
    cmds = []
    for _ in range(2):
        cmds.append('detail_line {"start": %s, "end": %s}' % (fmt(pt(dec)), fmt(pt(dec))))
    return cmds


def tests_for(cmds, k):
    out = []
    if k in ('corner', 'cornerl'):
        out.append('corner {"ids": [100002, 100003]}')
        out.append('corner {"ids": [100003, 100002]}')
        for _ in range(3):
            out.append('corner {"ids": [100002, 100003], "keep": [%s, %s]}' % (fmt(pt()), fmt(pt())))
    if k in ('split', 'splitl'):
        for _ in range(5):
            wid = random.choice([100002, 100003])
            out.append('split {"id": %d, "at": %s}' % (wid, fmt(pt(3))))
    if k in ('fillet', 'filletl'):
        for _ in range(4):
            r = random.choice([random.uniform(2, 3000), float(random.randint(2, 3000))])
            out.append('fillet {"ids": [100002, 100003], "radius": %s}' % json.dumps(round(r, 3)))
    return out


def split_tests_targeted(cmds):
    return []


total = same = 0
for i in range(n):
    if kind in ('corner', 'split', 'fillet'):
        cmds = walls_case()
    else:
        cmds = lines_case()
    try:
        text = build(cmds)
    except Exception as ex:
        continue
    src = '/tmp/edit-ops/fz_in.bimcraft'
    open(src, 'w').write(text)
    tests = tests_for(cmds, kind)
    if kind in ('split', 'splitl'):
        # points on the walls/lines too
        d = json.loads(text)
        for wid in (100002, 100003):
            e = d['elements'][str(wid)]
            s, e2 = e['start'], e['end']
            for _ in range(3):
                u = random.uniform(-0.05, 1.05)
                off = random.choice([0, 0, 50, 99.9, 150])
                p = [s[0] + (e2[0] - s[0]) * u + random.uniform(-off, off), s[1] + (e2[1] - s[1]) * u + random.uniform(-off, off)]
                tests.append('split {"id": %d, "at": %s}' % (wid, fmt([round(p[0], 4), round(p[1], 4)])))
    for c in tests:
        code, out, err, proj = T.run(ORIG, src, [c])
        mc, mo, me, mp = T.run(MINE, src, [c])
        ok = (code == mc and T.norm(out) == T.norm(mo) and T.norm(err) == T.norm(me) and T.norm(proj or '') == T.norm(mp or ''))
        total += 1
        if ok:
            same += 1
            if verbose:
                print('SAME', c, (out.splitlines()[1] if code == 0 else err.strip())[:200])
        else:
            print('DIFF case %d: %s' % (i, ' | '.join(cmds)))
