import json, math, sys, itertools
samples = json.load(open(sys.argv[1] if len(sys.argv) > 1 else '/tmp/edit-ops/an2_samples.json'))

LEN = {
    'hyp': lambda d: math.hypot(d[0], d[1]),
    'sqrt': lambda d: math.sqrt(d[0] * d[0] + d[1] * d[1]),
}
DIR = {
    'div': lambda d, L: [d[0] / L, d[1] / L],
    'mulrecip': lambda d, L: [d[0] * (1 / L), d[1] * (1 / L)],
}


def P_variants(s0, e0, off):
    d = [e0[0] - s0[0], e0[1] - s0[1]]
    out = {}
    for ln, lf in LEN.items():
        L = lf(d)
        for dn, df in DIR.items():
            u = df(d, L)
            out['s+u*o/%s/%s' % (ln, dn)] = [s0[0] + u[0] * off, s0[1] + u[1] * off]
            out['s+o*u/%s/%s' % (ln, dn)] = [s0[0] + off * u[0], s0[1] + off * u[1]]
        t = off / L
        out['lerp/%s' % ln] = [s0[0] + d[0] * t, s0[1] + d[1] * t]
        out['lerp2/%s' % ln] = [s0[0] * (1 - t) + e0[0] * t, s0[1] * (1 - t) + e0[1] * t]
        out['dmo/%s' % ln] = [s0[0] + d[0] * off / L, s0[1] + d[1] * off / L]
    return out


def S_variants(P, s1, e1):
    d = [e1[0] - s1[0], e1[1] - s1[1]]
    q = [P[0] - s1[0], P[1] - s1[1]]
    out = {}
    dd = d[0] * d[0] + d[1] * d[1]
    for ln, lf in LEN.items():
        L = lf(d)
        for dn, df in DIR.items():
            u = df(d, L)
            out['dot(q,u)/%s/%s' % (ln, dn)] = q[0] * u[0] + q[1] * u[1]
            out['dot(u,q)/%s/%s' % (ln, dn)] = u[0] * q[0] + u[1] * q[1]
        out['dot/L/%s' % ln] = (q[0] * d[0] + q[1] * d[1]) / L
        out['dot*rL/%s' % ln] = (q[0] * d[0] + q[1] * d[1]) * (1 / L)
        out['t*L/%s' % ln] = ((q[0] * d[0] + q[1] * d[1]) / dd) * L
    return out


score = {}
for (s0, e0, s1, e1, off, target) in samples:
    for pn, P in P_variants(s0, e0, off).items():
        for sn, v in S_variants(P, s1, e1).items():
            score.setdefault((pn, sn), 0)
            if v == target:
                score[(pn, sn)] += 1
for k, v in sorted(score.items(), key=lambda kv: -kv[1])[:12]:
    print(v, '/', len(samples), k)

