use std::collections::BTreeMap;

type P = [f64; 2];

fn lens(d: P) -> Vec<(&'static str, f64)> {
    vec![
        ("hyp", d[0].hypot(d[1])),
        ("sqrt", (d[0] * d[0] + d[1] * d[1]).sqrt()),
        ("fma", d[0].mul_add(d[0], d[1] * d[1]).sqrt()),
        ("fma2", d[1].mul_add(d[1], d[0] * d[0]).sqrt()),
    ]
}

fn dirs(d: P, l: f64) -> Vec<(&'static str, P)> {
    vec![("div", [d[0] / l, d[1] / l]), ("rec", [d[0] * (1.0 / l), d[1] * (1.0 / l)])]
}

fn main() {
    let path = std::env::args().nth(1).unwrap();
    let text = std::fs::read_to_string(path).unwrap();
    let mut score: BTreeMap<String, usize> = BTreeMap::new();
    let mut n = 0;
    for line in text.lines() {
        let v: Vec<f64> = line.split_whitespace().map(|x| x.parse().unwrap()).collect();
        if v.len() < 10 {
            continue;
        }
        n += 1;
        let (s0, e0, s1, e1, off, target) = ([v[0], v[1]], [v[2], v[3]], [v[4], v[5]], [v[6], v[7]], v[8], v[9]);
        let d0 = [e0[0] - s0[0], e0[1] - s0[1]];
        let d1 = [e1[0] - s1[0], e1[1] - s1[1]];
        for (ln0, l0) in lens(d0) {
            for (dn0, u0) in dirs(d0, l0) {
                let mut ps: Vec<(String, P)> = vec![
                    ("s+u*o".into(), [s0[0] + u0[0] * off, s0[1] + u0[1] * off]),
                    ("fma(u,o,s)".into(), [u0[0].mul_add(off, s0[0]), u0[1].mul_add(off, s0[1])]),
                ];
                let t = off / l0;
                ps.push(("lerp".into(), [s0[0] + d0[0] * t, s0[1] + d0[1] * t]));
                for (pn, p) in ps {
                    let q = [p[0] - s1[0], p[1] - s1[1]];
                    for (ln1, l1) in lens(d1) {
                        for (dn1, u1) in dirs(d1, l1) {
                            let cands: Vec<(&str, f64)> = vec![
                                ("dot", q[0] * u1[0] + q[1] * u1[1]),
                                ("fma01", q[0].mul_add(u1[0], q[1] * u1[1])),
                                ("fma10", q[1].mul_add(u1[1], q[0] * u1[0])),
                            ];
                            for (cn, x) in cands {
                                let k = format!("{}/{}/{} -> {}/{}/{}", ln0, dn0, pn, ln1, dn1, cn);
                                *score.entry(k).or_insert(0) += (x == target) as usize;
                            }
                        }
                        let dd = d1[0] * d1[0] + d1[1] * d1[1];
                        let dt = q[0] * d1[0] + q[1] * d1[1];
                        for (cn, x) in [("dot/L", dt / l1), ("t*L", dt / dd * l1), ("hypq", q[0].hypot(q[1]))] {
                            let k = format!("{}/{}/{} -> {}/{}", ln0, dn0, pn, ln1, cn);
                            *score.entry(k).or_insert(0) += (x == target) as usize;
                        }
                    }
                }
            }
        }
    }
    let mut v: Vec<(String, usize)> = score.into_iter().collect();
    v.sort_by(|a, b| b.1.cmp(&a.1));
    for (k, s) in v.iter().take(15) {
        println!("{} / {} {}", s, n, k);
    }
}

