fn sq(x: f64) -> (f64, f64) {
    let split = 134217729.0; // 0x1p27 + 1
    let xc = x * split;
    let xh = x - xc + xc;
    let xl = x - xh;
    let hi = x * x;
    let lo = xh * xh - hi + 2.0 * xh * xl + xl * xl;
    (hi, lo)
}

pub fn musl_hypot(x: f64, y: f64) -> f64 {
    let mut ux = x.to_bits() & (u64::MAX >> 1);
    let mut uy = y.to_bits() & (u64::MAX >> 1);
    if ux < uy {
        std::mem::swap(&mut ux, &mut uy);
    }
    let ex = (ux >> 52) as i32;
    let ey = (uy >> 52) as i32;
    let mut x = f64::from_bits(ux);
    let mut y = f64::from_bits(uy);
    if ey == 0x7ff {
        return y;
    }
    if ex == 0x7ff || uy == 0 {
        return x;
    }
    if ex - ey > 64 {
        return x + y;
    }
    let mut z = 1.0;
    if ex > 0x3ff + 510 {
        z = f64::from_bits(((0x3ff + 700) as u64) << 52);
        x *= f64::from_bits(((0x3ff - 700) as u64) << 52);
        y *= f64::from_bits(((0x3ff - 700) as u64) << 52);
    } else if ey < 0x3ff - 450 {
        z = f64::from_bits(((0x3ff - 700) as u64) << 52);
        x *= f64::from_bits(((0x3ff + 700) as u64) << 52);
        y *= f64::from_bits(((0x3ff + 700) as u64) << 52);
    }
    let (hx, lx) = sq(x);
    let (hy, ly) = sq(y);
    z * (ly + lx + hy + hx).sqrt()
}

