/// A straight wall's ends once trimmed or extended to the corner `c`, keeping the part `k` is on
/// (a point exactly at the corner keeps the part toward the start). The end moves by how far it
/// is from the corner, as `move` moves a wall's end.
fn trim_wall(a: P, b: P, c: P, k: P) -> (P, P) {
    let d = sub(b, a);
    if dot(sub(k, c), d) > 0.0 {
        (add(a, sub(c, a)), b)
    } else {
        (a, add(b, sub(c, b)))
