use std::collections::BTreeMap;
type P = [f64; 2];
fn sub(a: P, b: P) -> P {
    [a[0] - b[0], a[1] - b[1]]
}
fn add(a: P, b: P) -> P {
    [a[0] + b[0], a[1] + b[1]]
}
fn mul(a: P, k: f64) -> P {
    [a[0] * k, a[1] * k]
}
fn dot(a: P, b: P) -> f64 {
    a[0] * b[0] + a[1] * b[1]
}
fn cross(a: P, b: P) -> f64 {
    a[0] * b[1] - a[1] * b[0]
}
fn hyp(a: P) -> f64 {
    a[0].hypot(a[1])
}
fn dir(a: P) -> P {
    let k = 1.0 / hyp(a);
    [a[0] * k, a[1] * k]
}
fn r3(x: f64) -> f64 {
    (x * 1000.0).round() / 1000.0
}

fn main() {
    let path = std::env::args().nth(1).unwrap();
    let text = std::fs::read_to_string(path).unwrap();
    let mut score: BTreeMap<String, usize> = BTreeMap::new();
    let mut n = 0;
    let mut tp_ok = 0;
    for line in text.lines() {
        let v: Vec<f64> = line.split_whitespace().map(|x| x.parse().unwrap()).collect();
        if v.len() < 14 {
            continue;
        }
        n += 1;
        let (a0, a1, b0, b1, r) = ([v[0], v[1]], [v[2], v[3]], [v[4], v[5]], [v[6], v[7]], v[8]);
        let (t1o, t2o, arc) = ([v[9], v[10]], [v[11], v[12]], v[13]);
        let mut add_s = |k: String, x: f64| {
            *score.entry(k).or_insert(0) += (x == arc) as usize;
        };
        // corner
        let ra = sub(a1, a0);
        let rb = sub(b1, b0);
        let ta = cross(sub(b0, a0), rb) / cross(ra, rb);
        let c = add(a0, mul(ra, ta));
        let ma = mul(add(a0, a1), 0.5);
        let mb = mul(add(b0, b1), 0.5);
        let fa = if dot(sub(ma, c), ra) >= 0.0 { a1 } else { a0 };
        let fb = if dot(sub(mb, c), rb) >= 0.0 { b1 } else { b0 };
        for (dn, u, w) in [("rec", dir(sub(fa, c)), dir(sub(fb, c))), ("div", { let d = sub(fa, c); let l = hyp(d); [d[0] / l, d[1] / l] }, { let d = sub(fb, c); let l = hyp(d); [d[0] / l, d[1] / l] })] {
            let sign = if cross(u, w) > 0.0 { -1.0 } else { 1.0 };
            let thetas = [("acos", dot(u, w).clamp(-1.0, 1.0).acos()), ("atan2", cross(u, w).abs().atan2(dot(u, w)))];
            for (tn, th) in thetas {
                let t = r / (th / 2.0).tan();
                let t1 = add(c, mul(u, t));
                let t2 = add(c, mul(w, t));
                if dn == "rec" && tn == "acos" && [r3(t1[0]), r3(t1[1])] == t1o && [r3(t2[0]), r3(t2[1])] == t2o {
                    tp_ok += 1;
                }
                let pre = format!("{}/{}", dn, tn);
                add_s(format!("{} pi-th deg", pre), sign * (std::f64::consts::PI - th).to_degrees());
                add_s(format!("{} 180-thdeg", pre), sign * (180.0 - th.to_degrees()));
                // centre
