    [a[0] * k, a[1] * k]
}
fn r3(x: f64) -> f64 {
    (x * 1000.0).round() / 1000.0
}
fn r3p(p: P) -> P {
    [r3(p[0]), r3(p[1])]
}
const PI: f64 = std::f64::consts::PI;
fn norm_pi(mut a: f64) -> f64 {
    while a > PI {
        a -= 2.0 * PI;
    }
    while a < -PI {
        a += 2.0 * PI;
    }
    a
}

/// arc degrees from start, through point and end (circumcircle)
fn arc3(s: P, m: P, e: P) -> Vec<(&'static str, f64)> {
    let mut out = Vec::new();
    // circumcentre
    let d = 2.0 * (s[0] * (m[1] - e[1]) + m[0] * (e[1] - s[1]) + e[0] * (s[1] - m[1]));
    let ss = dot(s, s);
    let mm = dot(m, m);
    let ee = dot(e, e);
    let ux = (ss * (m[1] - e[1]) + mm * (e[1] - s[1]) + ee * (s[1] - m[1])) / d;
    let uy = (ss * (e[0] - m[0]) + mm * (s[0] - e[0]) + ee * (m[0] - s[0])) / d;
    let o = [ux, uy];
    let a0 = (s[1] - o[1]).atan2(s[0] - o[0]);
    let am = (m[1] - o[1]).atan2(m[0] - o[0]);
    let a1 = (e[1] - o[1]).atan2(e[0] - o[0]);
    let ccw = cross(sub(m, s), sub(e, m)) > 0.0;
    let mut sw = a1 - a0;
    if ccw {
        while sw <= 0.0 {
            sw += 2.0 * PI;
        }
    } else {
        while sw >= 0.0 {
            sw -= 2.0 * PI;
        }
    }
    out.push(("circ sweep", sw.to_degrees()));
    let _ = am;
    // sagitta
    let ch = sub(e, s);
    let half = hyp(ch) / 2.0;
    let mid = mul(add(s, e), 0.5);
    let sag = hyp(sub(m, mid));
    let sign = if ccw { 1.0 } else { -1.0 };
    out.push(("4atan", sign * (4.0 * (sag / half).atan()).to_degrees()));
    out.push(("4atan2", sign * 4.0 * (sag / half).atan().to_degrees()));
    // inscribed angle: angle at m between s and e
    let q1 = sub(s, m);
    let q2 = sub(e, m);
    let ang = cross(q1, q2).abs().atan2(dot(q1, q2));
    out.push(("2(pi-insc)", sign * (2.0 * (PI - ang)).to_degrees()));
    out.push(("360-2insc", sign * (360.0 - 2.0 * ang.to_degrees())));
    out
}

fn main() {
    let path = std::env::args().nth(1).unwrap();
    let text = std::fs::read_to_string(path).unwrap();
    let mut score: BTreeMap<String, usize> = BTreeMap::new();
    let mut n = 0;
    for line in text.lines() {
        let v: Vec<f64> = line.split_whitespace().map(|x| x.parse().unwrap()).collect();
        if v.len() < 14 {
            continue;
        }
        n += 1;
        let (a0, a1, b0, b1, r) = ([v[0], v[1]], [v[2], v[3]], [v[4], v[5]], [v[6], v[7]], v[8]);
        let arc = v[13];
        let mut add_s = |k: String, x: f64| {
            *score.entry(k).or_insert(0) += (x == arc) as usize;
        };
        let ra = sub(a1, a0);
        let rb = sub(b1, b0);
        let ta = cross(sub(b0, a0), rb) / cross(ra, rb);
        let c = add(a0, mul(ra, ta));
        let ma = mul(add(a0, a1), 0.5);
        let mb = mul(add(b0, b1), 0.5);
        let fa = if dot(sub(ma, c), ra) >= 0.0 { a1 } else { a0 };
        let fb = if dot(sub(mb, c), rb) >= 0.0 { b1 } else { b0 };
        let u = dir(sub(fa, c));
        let w = dir(sub(fb, c));
        let sign = if cross(u, w) > 0.0 { -1.0 } else { 1.0 };
        let th = dot(u, w).clamp(-1.0, 1.0).acos();
        let t = r / (th / 2.0).tan();
        let t1 = add(c, mul(u, t));
        let t2 = add(c, mul(w, t));
        // centres
        let bis = dir(add(u, w));
        let side = if cross(u, w) > 0.0 { 1.0 } else { -1.0 };
        let os = [
            ("bis", add(c, mul(bis, r / (th / 2.0).sin()))),
            ("n1", add(t1, mul([-u[1] * side, u[0] * side], r))),
            ("n2", add(t2, mul([w[1] * side, -w[0] * side], r))),
            ("bis2", add(c, mul(bis, (t * t + r * r).sqrt()))),
            ("bis3", add(c, mul(bis, t.hypot(r)))),
        ];
        for (on, o) in os {
            for (pn, p1, p2) in [("raw", t1, t2), ("rnd", r3p(t1), r3p(t2))] {
                let q1 = sub(p1, o);
                let q2 = sub(p2, o);
                let a1_ = q1[1].atan2(q1[0]);
