                add_s(format!("{} {} atan2diff deg", on, pn), {
                    let mut d = a2_.to_degrees() - a1_.to_degrees();
                    while d > 180.0 { d -= 360.0; }
                    while d < -180.0 { d += 360.0; }
                    d
                });
                add_s(format!("{} {} atan2(cr,dt)", on, pn), cross(q1, q2).atan2(dot(q1, q2)).to_degrees());
                // midpoint of the arc through the corner direction
                let m = add(o, mul(dir(sub(c, o)), r));
                for (k, x) in arc3(p1, m, p2) {
                    add_s(format!("{} {} arc3 {}", on, pn, k), x);
                }
                let m2 = add(o, mul(dir(sub(c, o)), hyp(q1)));
                for (k, x) in arc3(p1, m2, p2) {
                    add_s(format!("{} {} arc3b {}", on, pn, k), x);
                }
            }
        }
        add_s("turn".into(), cross(mul(u, -1.0), w).atan2(dot(mul(u, -1.0), w)).to_degrees());
        add_s("pi-th".into(), sign * (PI - th).to_degrees());
    }
    let mut v: Vec<(String, usize)> = score.into_iter().collect();
    v.sort_by(|a, b| b.1.cmp(&a.1));
    for (k, s) in v.iter().take(15) {
        println!("{} / {} {}", s, n, k);
    }
}

