            *score.entry(k.to_string()).or_insert(0) += (x == arc) as usize;
        };
        for (pn, q1, q2) in [("raw", p1, p2), ("rnd", [r3(p1[0]), r3(p1[1])], [r3(p2[0]), r3(p2[1])]), ("orig", t1o, t2o)] {
            let d1 = sub(c, q1);
            let d2 = sub(q2, c);
            add_s(&format!("{} turn pts", pn), cross(d1, d2).atan2(dot(d1, d2)).to_degrees());
            add_s(&format!("{} turn pts norm", pn), { let e1 = dir_rec(d1); let e2 = dir_rec(d2); cross(e1, e2).atan2(dot(e1, e2)).to_degrees() });
            add_s(&format!("{} turn angles", pn), norm_pi(d2[1].atan2(d2[0]) - d1[1].atan2(d1[0])).to_degrees());
            let e1 = sub(q1, c);
            let e2 = sub(q2, c);
            let inner = cross(e1, e2).abs().atan2(dot(e1, e2));
            let sgn = if cross(d1, d2) > 0.0 { 1.0 } else { -1.0 };
            add_s(&format!("{} pi-inner", pn), sgn * (PI - inner).to_degrees());
            add_s(&format!("{} 180-inner", pn), sgn * (180.0 - inner.to_degrees()));
            let inner2 = (dot(e1, e2) / (hyp(e1) * hyp(e2))).clamp(-1.0, 1.0).acos();
            add_s(&format!("{} pi-inner acos", pn), sgn * (PI - inner2).to_degrees());
            add_s(&format!("{} 180-inner acos", pn), sgn * (180.0 - inner2.to_degrees()));
        }
    }
    let mut v: Vec<(String, usize)> = score.into_iter().collect();
    v.sort_by(|a, b| b.1.cmp(&a.1));
    for (k, s) in v.iter().take(12) {
        println!("{} / {} {}", s, n, k);
    }
}

use std::collections::BTreeMap;
type P = [f64; 2];
fn sub(a: P, b: P) -> P {
    [a[0] - b[0], a[1] - b[1]]
}
fn add(a: P, b: P) -> P {
    [a[0] + b[0], a[1] + b[1]]
}
fn mul(a: P, k: f64) -> P {
    [a[0] * k, a[1] * k]
}
fn dot(a: P, b: P) -> f64 {
    a[0] * b[0] + a[1] * b[1]
}
fn cross(a: P, b: P) -> f64 {
    a[0] * b[1] - a[1] * b[0]
}
fn hyp(a: P) -> f64 {
    a[0].hypot(a[1])
}
fn dir_rec(a: P) -> P {
    let k = 1.0 / hyp(a);
    [a[0] * k, a[1] * k]
}
fn r3(x: f64) -> f64 {
    (x * 1000.0).round() / 1000.0
}
const PI: f64 = std::f64::consts::PI;
fn norm_pi(mut a: f64) -> f64 {
    while a > PI {
        a -= 2.0 * PI;
    }
    while a < -PI {
        a += 2.0 * PI;
    }
    a
}

fn main() {
    let path = std::env::args().nth(1).unwrap();
    let text = std::fs::read_to_string(path).unwrap();
    let mut score: BTreeMap<String, usize> = BTreeMap::new();
    let mut n = 0;
    for line in text.lines() {
        let v: Vec<f64> = line.split_whitespace().map(|x| x.parse().unwrap()).collect();
        if v.len() < 14 {
            continue;
        }
        n += 1;
        let (a0, a1, b0, b1, r) = ([v[0], v[1]], [v[2], v[3]], [v[4], v[5]], [v[6], v[7]], v[8]);
        let (t1o, t2o, arc) = ([v[9], v[10]], [v[11], v[12]], v[13]);
        let ra = sub(a1, a0);
        let rb = sub(b1, b0);
        let ta = cross(sub(b0, a0), rb) / cross(ra, rb);
        let c = add(a0, mul(ra, ta));
        let ma = mul(add(a0, a1), 0.5);
        let mb = mul(add(b0, b1), 0.5);
        let fa = if dot(sub(ma, c), ra) >= 0.0 { a1 } else { a0 };
        let fb = if dot(sub(mb, c), rb) >= 0.0 { b1 } else { b0 };
        let u = dir_rec(sub(fa, c));
        let w = dir_rec(sub(fb, c));
        let th = dot(u, w).clamp(-1.0, 1.0).acos();
        let t = r / (th / 2.0).tan();
        let p1 = add(c, mul(u, t));
        let p2 = add(c, mul(w, t));
        let mut add_s = |k: &str, x: f64| {
            *score.entry(k.to_string()).or_insert(0) += (x == arc) as usize;
        };
        for (pn, q1, q2) in [("raw", p1, p2), ("rnd", [r3(p1[0]), r3(p1[1])], [r3(p2[0]), r3(p2[1])]), ("orig", t1o, t2o)] {
            let d1 = sub(c, q1);
            let d2 = sub(q2, c);
            add_s(&format!("{} turn pts", pn), cross(d1, d2).atan2(dot(d1, d2)).to_degrees());
            add_s(&format!("{} turn pts norm", pn), { let e1 = dir_rec(d1); let e2 = dir_rec(d2); cross(e1, e2).atan2(dot(e1, e2)).to_degrees() });
            add_s(&format!("{} turn angles", pn), norm_pi(d2[1].atan2(d2[0]) - d1[1].atan2(d1[0])).to_degrees());
            let e1 = sub(q1, c);
            let e2 = sub(q2, c);
            let inner = cross(e1, e2).abs().atan2(dot(e1, e2));
            let sgn = if cross(d1, d2) > 0.0 { 1.0 } else { -1.0 };
            add_s(&format!("{} pi-inner", pn), sgn * (PI - inner).to_degrees());
            add_s(&format!("{} 180-inner", pn), sgn * (180.0 - inner.to_degrees()));
            let inner2 = (dot(e1, e2) / (hyp(e1) * hyp(e2))).clamp(-1.0, 1.0).acos();
            add_s(&format!("{} pi-inner acos", pn), sgn * (PI - inner2).to_degrees());
            add_s(&format!("{} 180-inner acos", pn), sgn * (180.0 - inner2.to_degrees()));
        }
    }
    let mut v: Vec<(String, usize)> = score.into_iter().collect();
    v.sort_by(|a, b| b.1.cmp(&a.1));
    for (k, s) in v.iter().take(12) {
        println!("{} / {} {}", s, n, k);
    }
}

//! Arcs: corner with arcs of detail lines, and curved walls split in two.

use super::common::*;
use super::ops_geom::*;
use crate::json::Value;
use crate::project::Project;

const TAU: f64 = std::f64::consts::PI * 2.0;

/// Where on an arc the point nearest `p` is: how far round from its start (radians, along its
/// sweep, 0 to |sweep|), and how far `p` is from it. Past its ends, its nearer end.
pub fn arc_nearest(arc: &Arc, p: P) -> (f64, f64) {
    let sw = arc.sweep.abs();
    let ang = (p[1] - arc.c[1]).atan2(p[0] - arc.c[0]);
    let mut da = (ang - arc.a0) * arc.sweep.signum();
    da = da.rem_euclid(TAU);
    if da <= sw {
        let d = (dist(p, arc.c) - arc.r).abs();
        return (da, d);
    }
    // past an end: the nearer one
    let to_end = da - sw;
    let to_start = TAU - da;
    let (u, q) = if to_start <= to_end { (0.0, arc.at(arc.a0)) } else { (sw, arc.at(arc.a0 + arc.sweep)) };
    (u, dist(p, q))
}

pub fn corner_arcs(
    pr: &mut Project,
    ia: u64,
    ib: u64,
    la: (P, P, f64),
    lb: (P, P, f64),
    keep: Option<[P; 2]>,
) -> R<Value> {
    let _ = (pr, ia, ib, la, lb, keep);
    Err("corner: arcs not supported here".into())
}

/// A curved wall split at `at`: two arcs on its circle, its doors and windows with their part.
pub fn split_arc_wall(pr: &mut Project, id: u64, at: P) -> R<Value> {
    let e = pr.el(id).unwrap().clone();
    let (a, b, deg) = wall_line(&e);
    let arc = arc_of(a, b, deg);
    let tol = wall_thickness(pr, &e) / 2.0 + 100.0;
    let (u, d) = arc_nearest(&arc, at);
    if d > tol {
        return Err(format!("split: {} isn't on wall {}", pt_text(at), id));
    }
    let s = u * arc.r;
    let len = arc.len();
    if !(s > 1.0 && len - s > 1.0) {
        return Err("split: split between the wall's ends".into());
    }
    let ops = openings(pr, id);
    for oid in &ops {
        let o = pr.el(*oid).unwrap();
        let w = opening_width(pr, o);
        if (offset_of(o) - s).abs() < w / 2.0 - 1.0 {
            return Err(format!("split: {} {} is in the way; split elsewhere", cat_of(o), oid));
        }
    }
    let q = r3p(arc.at(arc.a0 + arc.sweep.signum() * u));
    let first = u.to_degrees() * arc.sweep.signum();
    let second = deg - first;
    let nid = pr.alloc_id();
    let g = crate::rand::guid();
    let mut ne = e.clone();
    super::fillet::drop_mass_face(&mut ne);
    ne.set("guid", Value::s(&g));
    set_pt(&mut ne, "start", q);
    ne.set("arc", Value::f(super::fillet::r9(second)));
    {
        let w = pr.el_mut(id).unwrap();
        super::fillet::drop_mass_face(w);
        set_pt(w, "end", q);
        w.set("arc", Value::f(super::fillet::r9(first)));
    }
    for oid in ops {
        let o = pr.el_mut(oid).unwrap();
        let off = offset_of(o);
        if off > s {
            o.set("host", Value::s(&g));
            o.set("offset", Value::f(off - s));
        }
    }
    pr.elements.insert(nid, ne);
    Ok(crate::jobj! {"ids" => vec![Value::u(id), Value::u(nid)]})
}

use std::collections::BTreeMap;
type P = [f64; 2];
fn sub(a: P, b: P) -> P {
    [a[0] - b[0], a[1] - b[1]]
}
fn add(a: P, b: P) -> P {
    [a[0] + b[0], a[1] + b[1]]
}
fn mul(a: P, k: f64) -> P {
    [a[0] * k, a[1] * k]
}
fn hyp(a: P) -> f64 {
    a[0].hypot(a[1])
}
const TAU: f64 = std::f64::consts::PI * 2.0;

fn main() {
    let path = std::env::args().nth(1).unwrap();
    let text = std::fs::read_to_string(path).unwrap();
    let mut score: BTreeMap<String, usize> = BTreeMap::new();
    let mut n = 0;
    for line in text.lines() {
        let v: Vec<f64> = line.split_whitespace().map(|x| x.parse().unwrap()).collect();
        if v.len() < 11 {
            continue;
        }
        n += 1;
        let (s0, e0, deg, at, off, target) = ([v[0], v[1]], [v[2], v[3]], v[4], [v[5], v[6]], v[7], v[8]);
        let th = deg.to_radians();
        let ch = sub(e0, s0);
        let l = hyp(ch);
        let m = mul(add(s0, e0), 0.5);
        let mut add_s = |k: String, x: f64| {
            *score.entry(k).or_insert(0) += (x == target) as usize;
        };
        let rs = [("l/2/sin", l / 2.0 / (th / 2.0).sin().abs()), ("l/(2sin)", l / (2.0 * (th / 2.0).sin().abs()))];
        for (rn, r) in rs {
            let n_ = [-ch[1] / l, ch[0] / l];
            let n2 = { let k = 1.0 / l; [-ch[1] * k, ch[0] * k] };
            let ds = [("l/2/tan", l / 2.0 / (th / 2.0).tan()), ("r*cos", r * (th / 2.0).cos() * (th / 2.0).tan().signum()), ("sqrt", (r * r - l * l / 4.0).max(0.0).sqrt() * (th / 2.0).tan().signum())];
            for (dn, d) in ds {
                for (nn, nv) in [("div", n_), ("rec", n2)] {
                    let c = add(m, mul(nv, d));
                    let a0 = (s0[1] - c[1]).atan2(s0[0] - c[0]);
                    let aa = (at[1] - c[1]).atan2(at[0] - c[0]);
                    let sg = th.signum();
                    let da = ((aa - a0) * sg).rem_euclid(TAU);
                    let pre = format!("{} {} {}", rn, dn, nn);
                    add_s(format!("{} off-da*r", pre), off - da * r);
                    add_s(format!("{} off-r*da", pre), off - r * da);
                    let len = r * th.abs();
                    add_s(format!("{} off-len*da/sw", pre), off - len * (da / th.abs()));
                    add_s(format!("{} off-da/sw*len", pre), off - da / th.abs() * len);
                    let dd = da.to_degrees();
                    add_s(format!("{} off-deg", pre), off - dd.to_radians() * r);
                    add_s(format!("{} off-deg2", pre), off - r * dd / 180.0 * std::f64::consts::PI);
                    // via a radius computed from the centre to the start
                    let r2 = hyp(sub(s0, c));
                    add_s(format!("{} off-da*r2", pre), off - da * r2);
                    // angle difference without rem_euclid but adding tau
                    let mut db = (aa - a0) * sg;
                    if db < 0.0 {
                        db += TAU;
                    }
                    add_s(format!("{} off-db*r", pre), off - db * r);
                    let mut dc = aa - a0;
                    if sg > 0.0 {
                        if dc < 0.0 { dc += TAU; }
                    } else if dc > 0.0 {
                        dc -= TAU;
                    }
                    add_s(format!("{} off-|dc|*r", pre), off - dc.abs() * r);
                    add_s(format!("{} off-dc*sg*r", pre), off - dc * sg * r);
                }
            }
        }
    }
    let mut v: Vec<(String, usize)> = score.into_iter().collect();
    v.sort_by(|a, b| b.1.cmp(&a.1));
    for (k, s) in v.iter().take(12) {
        println!("{} / {} {}", s, n, k);
    }
}

