// Reverse-engineering the nearest-point search on an arc: candidate algorithms against the
// original's split results (at x, at y, first arc degrees, end x, end y).
type P = [f64; 2];

struct ArcG {
    c: P,
    r: f64,
    a0: f64,
    th: f64,
}

fn arc_of(a: P, b: P, deg: f64) -> ArcG {
    let t = deg.to_radians();
    let ch = [b[0] - a[0], b[1] - a[1]];
    let l = ch[0].hypot(ch[1]);
    let r = l / 2.0 / (t / 2.0).sin().abs();
    let m = [(a[0] + b[0]) * 0.5, (a[1] + b[1]) * 0.5];
    let k = 1.0 / l;
    let n = [-ch[1] * k, ch[0] * k];
    let d = l / 2.0 / (t / 2.0).tan();
    let c = [m[0] + n[0] * d, m[1] + n[1] * d];
    let a0 = (a[1] - c[1]).atan2(a[0] - c[0]);
    ArcG { c, r, a0, th: t }
}

impl ArcG {
    fn at(&self, t: f64) -> P {
        let ang = self.a0 + self.th * t;
        [self.c[0] + self.r * ang.cos(), self.c[1] + self.r * ang.sin()]
    }
}

fn d2(a: P, b: P) -> f64 {
    let dx = a[0] - b[0];
    let dy = a[1] - b[1];
    dx * dx + dy * dy
}
fn d1(a: P, b: P) -> f64 {
    (a[0] - b[0]).hypot(a[1] - b[1])
}

fn golden(f: &dyn Fn(f64) -> f64, lo: f64, hi: f64, iters: usize, variant: u8) -> f64 {
    let g = (5f64.sqrt() - 1.0) / 2.0;
    let (mut a, mut b) = (lo, hi);
    match variant {
        0 => {
            // recompute both probes each step
            for _ in 0..iters {
                let c = b - g * (b - a);
                let d = a + g * (b - a);
                if f(c) < f(d) {
                    b = d;
                } else {
                    a = c;
                }
            }
            (a + b) / 2.0
        }
        1 => {
            for _ in 0..iters {
                let c = b - g * (b - a);
                let d = a + g * (b - a);
                if f(c) <= f(d) {
                    b = d;
                } else {
                    a = c;
                }
            }
            (a + b) / 2.0
        }
        _ => {
            // classic: reuse one probe
            let mut c = b - g * (b - a);
            let mut d = a + g * (b - a);
            let mut fc = f(c);
            let mut fd = f(d);
            for _ in 0..iters {
                if fc < fd {
                    b = d;
                    d = c;
                    fd = fc;
                    c = b - g * (b - a);
                    fc = f(c);
                } else {
                    a = c;
                    c = d;
                    fc = fd;
                    d = a + g * (b - a);
                    fd = f(d);
                }
            }
            (a + b) / 2.0
        }
    }
}

fn ternary(f: &dyn Fn(f64) -> f64, lo: f64, hi: f64, iters: usize) -> f64 {
    let (mut a, mut b) = (lo, hi);
    for _ in 0..iters {
        let m1 = a + (b - a) / 3.0;
        let m2 = b - (b - a) / 3.0;
        if f(m1) < f(m2) {
            b = m2;
        } else {
            a = m1;
        }
    }
    (a + b) / 2.0
}

fn main() {
    let files: Vec<String> = std::env::args().skip(1).collect();
    let mut rows: Vec<(P, f64, P)> = Vec::new();
    for f in &files {
        let text = std::fs::read_to_string(f).unwrap();
        for line in text.lines() {
            let v: Vec<f64> = line.split_whitespace().map(|x| x.parse().unwrap()).collect();
            if v.len() >= 5 {
                rows.push(([v[0], v[1]], v[2], [v[3], v[4]]));
            }
        }
    }
    let arc = arc_of([0.0, 0.0], [8000.0, 0.0], 90.0);
    let mut best: Vec<(usize, String)> = Vec::new();
    for nseg in [4usize, 8, 16] {
        for (mn, metric) in [("d2", d2 as fn(P, P) -> f64), ("d1", d1)] {
            for alg in 0..4u8 {
                for iters in 20..80usize {
                    let mut ok = 0;
                    for (p, a1, _q) in &rows {
                        let f = |t: f64| metric(arc.at(t), *p);
                        // nearest sample
                        let mut bi = 0;
                        let mut bd = f64::INFINITY;
                        for i in 0..=nseg {
                            let d = f(i as f64 / nseg as f64);
                            if d < bd {
                                bd = d;
                                bi = i;
                            }
                        }
                        let h = 1.0 / nseg as f64;
                        let lo = ((bi as f64 - 1.0) * h).max(0.0);
                        let hi = ((bi as f64 + 1.0) * h).min(1.0);
                        let t = match alg {
                            3 => ternary(&f, lo, hi, iters),
                            v => golden(&f, lo, hi, iters, v),
                        };
                        let deg = (arc.th * t).to_degrees();
                        if deg == *a1 {
                            ok += 1;
                        }
                    }
                    best.push((ok, format!("nseg {} {} alg {} iters {}", nseg, mn, alg, iters)));
                }
            }
        }
    }
    best.sort_by(|a, b| b.0.cmp(&a.0));
    for (ok, k) in best.iter().take(10) {
        println!("{} / {} {}", ok, rows.len(), k);
    }
}

