def golden(f, a, b, K, reuse=False, le=False):
    if not reuse:
        for _ in range(K):
            c = b - g * (b - a)
            d = a + g * (b - a)
            if (f(c) <= f(d)) if le else (f(c) < f(d)):
                b = d
