// Which arc centre/radius formula matches both the wall-split door offsets and the corner arcs.
use std::collections::BTreeMap;
type P = [f64; 2];
const TAU: f64 = std::f64::consts::PI * 2.0;
const PI: f64 = std::f64::consts::PI;

fn rot(a: P, t: f64) -> P {
    let (s, c) = t.sin_cos();
    [a[0] * c - a[1] * s, a[0] * s + a[1] * c]
}

/// candidate (centre, radius) formulas
fn centres(s: P, e: P, deg: f64) -> Vec<(&'static str, P, f64)> {
    let t = deg.to_radians();
    let h = t / 2.0;
    let ch = [e[0] - s[0], e[1] - s[1]];
    let l = ch[0].hypot(ch[1]);
    let m = [(s[0] + e[0]) * 0.5, (s[1] + e[1]) * 0.5];
    let k = 1.0 / l;
    let u = [ch[0] * k, ch[1] * k];
    let ud = [ch[0] / l, ch[1] / l];
    let n = [-u[1], u[0]];
    let nd = [-ud[1], ud[0]];
    let r1 = l / 2.0 / h.sin().abs();
    let r2 = l / (2.0 * h.sin().abs());
    let r3 = (l * 0.5) / h.sin().abs();
    let sg = t.signum();
    let mut out = Vec::new();
    for (rn, r) in [("r1", r1), ("r2", r2), ("r3", r3)] {
        let _ = rn;
        out.push(("mid tan", [m[0] + n[0] * (l / 2.0 / h.tan()), m[1] + n[1] * (l / 2.0 / h.tan())], r));
        out.push(("mid tan d", [m[0] + nd[0] * (l / 2.0 / h.tan()), m[1] + nd[1] * (l / 2.0 / h.tan())], r));
        out.push(("mid cos", [m[0] + n[0] * (r * h.cos() * sg), m[1] + n[1] * (r * h.cos() * sg)], r));
        let dd = (r * r - l * l / 4.0).max(0.0).sqrt() * if h.abs() < PI / 2.0 { 1.0 } else { -1.0 } * sg;
        out.push(("mid sqrt", [m[0] + n[0] * dd, m[1] + n[1] * dd], r));
        let v = rot(u, sg * (PI / 2.0) - h);
        out.push(("s rot", [s[0] + v[0] * r, s[1] + v[1] * r], r));
        let v2 = rot(ch, sg * (PI / 2.0) - h);
        out.push(("s rot ch", [s[0] + v2[0] * (r / l), s[1] + v2[1] * (r / l)], r));
        let w = rot(u, -sg * (PI / 2.0) + h);
        out.push(("e rot", [e[0] - w[0] * r * -1.0 * -1.0, e[1] - w[1] * r * -1.0 * -1.0], r));
        out.push(("half ch tan", [m[0] - ch[1] * (0.5 / h.tan()), m[1] + ch[0] * (0.5 / h.tan())], r));
        out.push(("half ch tan2", [m[0] - ch[1] / 2.0 / h.tan(), m[1] + ch[0] / 2.0 / h.tan()], r));
        out.push(("half ch cot", [m[0] - ch[1] * 0.5 * (h.cos() / h.sin()), m[1] + ch[0] * 0.5 * (h.cos() / h.sin())], r));
    }
    out
}

