        for (un, uu) in [("rec", u), ("div", ud)] {
            let n = [-uu[1], uu[0]];
            out.push((format!("midtan {} {}", rn, un), [m[0] + n[0] * (l / 2.0 / h.tan()), m[1] + n[1] * (l / 2.0 / h.tan())], r));
