                let ax = (x[1] - c[1]).atan2(x[0] - c[0]);
                let (from, to) = if ms { (ax, a1) } else { (a0, ax) };
                let val = sg * ((to - from) * sg).rem_euclid(TAU).to_degrees();
                *score.entry(format!("{} | {} | rem", cn, xn)).or_insert(0) += (val == target) as usize;
                // an end angle from the start's angle plus the old sweep
                let a1b = a0 + deg.to_radians();
                let (from2, to2) = if ms { (ax, a1b) } else { (a0, ax) };
                let val2 = sg * ((to2 - from2) * sg).rem_euclid(TAU).to_degrees();
                *score.entry(format!("{} | {} | a0+sweep", cn, xn)).or_insert(0) += (val2 == target) as usize;
                // the moved part relative to the old sweep
                let val3 = if ms { deg - sg * ((ax - a0) * sg).rem_euclid(TAU).to_degrees() } else { val };
                *score.entry(format!("{} | {} | deg-u", cn, xn)).or_insert(0) += (val3 == target) as usize;
            }
        }
