type P = [f64; 2];
fn main() {
    let r: f64 = 1.0000001;
    let c: P = [8000.0, 0.0];
    let u: P = [-1.0, 0.0];
    let v: P = [0.0, 1.0];
    let th = (u[0] * v[0] + u[1] * v[1]).acos();
    let t = r / (th / 2.0).tan();
    let t1 = [c[0] + u[0] * t, c[1] + u[1] * t];
    let t2 = [c[0] + v[0] * t, c[1] + v[1] * t];
    let bis = {
        let b = [u[0] + v[0], u[1] + v[1]];
        let l = b[0].hypot(b[1]);
        [b[0] * (1.0 / l), b[1] * (1.0 / l)]
    };
    let o = [c[0] + bis[0] * (r / (th / 2.0).sin()), c[1] + bis[1] * (r / (th / 2.0).sin())];
    let ch = [t2[0] - t1[0], t2[1] - t1[1]];
    let chl = ch[0].hypot(ch[1]);
    let half = chl / 2.0;
    let mid = [(t1[0] + t2[0]) / 2.0, (t1[1] + t2[1]) / 2.0];
    let dm = [mid[0] - o[0], mid[1] - o[1]];
    let dml = dm[0].hypot(dm[1]);
    println!("t1 {:?} t2 {:?} o {:?} ch {:?}", t1, t2, o, ch);
    let cands: Vec<(&str, f64)> = vec![
        ("2asin(ch/2r)", (2.0 * (chl / (2.0 * r)).asin()).to_degrees()),
        ("2atan2(half,dm)", (2.0 * half.atan2(dml)).to_degrees()),
        ("2atan2(half,sqrt)", (2.0 * half.atan2((r * r - half * half).sqrt())).to_degrees()),
        ("4atan(sag/half)", (4.0 * ((r - dml) / half).atan()).to_degrees()),
        ("180-2acos", 180.0 - (2.0 * (chl / (2.0 * r)).acos()).to_degrees()),
        ("2acos(dm/r)", (2.0 * (dml / r).acos()).to_degrees()),
        ("acos(1-ch2/2r2)", (1.0 - chl * chl / (2.0 * r * r)).acos().to_degrees()),
        ("acos dot", {
            let q1 = [t1[0] - o[0], t1[1] - o[1]];
            let q2 = [t2[0] - o[0], t2[1] - o[1]];
            ((q1[0] * q2[0] + q1[1] * q2[1]) / (q1[0].hypot(q1[1]) * q2[0].hypot(q2[1]))).acos().to_degrees()
        }),
        ("acos dot r2", {
            let q1 = [t1[0] - o[0], t1[1] - o[1]];
            let q2 = [t2[0] - o[0], t2[1] - o[1]];
            ((q1[0] * q2[0] + q1[1] * q2[1]) / (r * r)).acos().to_degrees()
        }),
        ("pi - acos(dot of chord dirs)", {
            let a = [c[0] - t1[0], c[1] - t1[1]];
            let b = [t2[0] - c[0], t2[1] - c[1]];
            ((a[0] * b[0] + a[1] * b[1]) / (a[0].hypot(a[1]) * b[0].hypot(b[1]))).acos().to_degrees()
        }),
        ("through mid", {
            // circumcircle through t1, the arc's middle and t2, the sweep from the inscribed angle
            let m = [o[0] + (c[0] - o[0]) / ((c[0] - o[0]).hypot(c[1] - o[1])) * r, o[1] + (c[1] - o[1]) / ((c[0] - o[0]).hypot(c[1] - o[1])) * r];
            let q1 = [t1[0] - m[0], t1[1] - m[1]];
            let q2 = [t2[0] - m[0], t2[1] - m[1]];
            let ang = (q1[0] * q2[1] - q1[1] * q2[0]).abs().atan2(q1[0] * q2[0] + q1[1] * q2[1]);
            (2.0 * (std::f64::consts::PI - ang)).to_degrees()
        }),
        ("4atan(sag/half) through", {
            let m = [o[0] + (c[0] - o[0]) / ((c[0] - o[0]).hypot(c[1] - o[1])) * r, o[1] + (c[1] - o[1]) / ((c[0] - o[0]).hypot(c[1] - o[1])) * r];
            let sag = (m[0] - mid[0]).hypot(m[1] - mid[1]);
            (4.0 * (sag / half).atan()).to_degrees()
        }),
    ];
    for (n, x) in cands {
        println!("{:32} {:?} {}", n, x, if x == 90.0000000000085 { "MATCH" } else { "" });
    }
}

