use std::collections::BTreeMap;
type P = [f64; 2];
fn sub(a: P, b: P) -> P {
    [a[0] - b[0], a[1] - b[1]]
}
fn add(a: P, b: P) -> P {
    [a[0] + b[0], a[1] + b[1]]
}
fn mul(a: P, k: f64) -> P {
    [a[0] * k, a[1] * k]
}
fn dot(a: P, b: P) -> f64 {
    a[0] * b[0] + a[1] * b[1]
}
fn cross(a: P, b: P) -> f64 {
    a[0] * b[1] - a[1] * b[0]
}
fn hyp(a: P) -> f64 {
    a[0].hypot(a[1])
}
fn dir(a: P) -> P {
    let k = 1.0 / hyp(a);
    [a[0] * k, a[1] * k]
}
const PI: f64 = std::f64::consts::PI;
fn norm_pi(mut a: f64) -> f64 {
    while a > PI {
        a -= 2.0 * PI;
    }
    while a <= -PI {
        a += 2.0 * PI;
    }
    a
}

fn main() {
    let text = std::fs::read_to_string(std::env::args().nth(1).unwrap()).unwrap();
    let mut score: BTreeMap<String, usize> = BTreeMap::new();
    let mut n = 0;
    for line in text.lines() {
        let v: Vec<f64> = line.split_whitespace().map(|x| x.parse().unwrap()).collect();
        if v.len() < 14 {
            continue;
        }
        n += 1;
        let (a0, a1, b0, b1, r) = ([v[0], v[1]], [v[2], v[3]], [v[4], v[5]], [v[6], v[7]], v[8]);
        let arc = v[13];
        let ra = sub(a1, a0);
        let rb = sub(b1, b0);
        let ta = cross(sub(b0, a0), rb) / cross(ra, rb);
        let c = add(a0, mul(ra, ta));
        let ma = mul(add(a0, a1), 0.5);
        let mb = mul(add(b0, b1), 0.5);
        let fa = if dot(sub(ma, c), ra) >= 0.0 { a1 } else { a0 };
        let fb = if dot(sub(mb, c), rb) >= 0.0 { b1 } else { b0 };
        let u = dir(sub(fa, c));
        let w = dir(sub(fb, c));
        let th = dot(u, w).clamp(-1.0, 1.0).acos();
        let t = r / (th / 2.0).tan();
        let t1 = add(c, mul(u, t));
        let t2 = add(c, mul(w, t));
        let ch = sub(t2, t1);
        let ach = ch[1].atan2(ch[0]);
        let mut add_s = |k: &str, x: f64| {
            *score.entry(k.to_string()).or_insert(0) += (x == arc) as usize;
        };
        for (tn, tg) in [("-u", mul(u, -1.0)), ("c-t1", sub(c, t1)), ("dir(c-t1)", dir(sub(c, t1))), ("a1-a0 dir", if fa == a0 { ra } else { mul(ra, -1.0) })] {
            let atg = tg[1].atan2(tg[0]);
            add_s(&format!("2*(ach-atg) {}", tn), (2.0 * norm_pi(ach - atg)).to_degrees());
            add_s(&format!("2*deg {}", tn), 2.0 * norm_pi(ach - atg).to_degrees());
            add_s(&format!("deg2 {}", tn), {
                let mut d = ach.to_degrees() - atg.to_degrees();
                while d > 180.0 { d -= 360.0; }
                while d <= -180.0 { d += 360.0; }
                2.0 * d
            });
            add_s(&format!("2atan2(cr,dt) {}", tn), (2.0 * cross(tg, ch).atan2(dot(tg, ch))).to_degrees());
            add_s(&format!("2atan2(cr,dt) b {}", tn), 2.0 * cross(tg, ch).atan2(dot(tg, ch)).to_degrees());
        }
    }
    let mut v: Vec<(String, usize)> = score.into_iter().collect();
    v.sort_by(|a, b| b.1.cmp(&a.1));
    for (k, s) in v.iter().take(12) {
        println!("{} / {} {}", s, n, k);
    }
}

