use std::collections::BTreeMap;
type P = [f64; 2];
fn sub(a: P, b: P) -> P {
    [a[0] - b[0], a[1] - b[1]]
}
fn add(a: P, b: P) -> P {
    [a[0] + b[0], a[1] + b[1]]
}
fn mul(a: P, k: f64) -> P {
    [a[0] * k, a[1] * k]
}
fn dot(a: P, b: P) -> f64 {
    a[0] * b[0] + a[1] * b[1]
}
fn cross(a: P, b: P) -> f64 {
    a[0] * b[1] - a[1] * b[0]
}
fn hyp(a: P) -> f64 {
    a[0].hypot(a[1])
}
fn dir(a: P) -> P {
    let k = 1.0 / hyp(a);
    [a[0] * k, a[1] * k]
}
fn dird(a: P) -> P {
    let l = hyp(a);
    [a[0] / l, a[1] / l]
}
fn r3(x: f64) -> f64 {
    (x * 1000.0).round() / 1000.0
}

fn main() {
    let text = std::fs::read_to_string(std::env::args().nth(1).unwrap()).unwrap();
    let mut score: BTreeMap<String, usize> = BTreeMap::new();
    let mut n = 0;
    for line in text.lines() {
        let v: Vec<f64> = line.split_whitespace().map(|x| x.parse().unwrap()).collect();
        if v.len() < 14 {
            continue;
        }
        n += 1;
        let (a0, a1, b0, b1, r) = ([v[0], v[1]], [v[2], v[3]], [v[4], v[5]], [v[6], v[7]], v[8]);
        let (t1o, t2o, arc) = ([v[9], v[10]], [v[11], v[12]], v[13]);
        let ra = sub(a1, a0);
        let rb = sub(b1, b0);
        let ta = cross(sub(b0, a0), rb) / cross(ra, rb);
        let tb = cross(sub(b0, a0), ra) / cross(ra, rb);
        for (cn, c) in [("cA", add(a0, mul(ra, ta))), ("cB", add(b0, mul(rb, tb)))] {
            let ma = mul(add(a0, a1), 0.5);
            let mb = mul(add(b0, b1), 0.5);
            let fa = if dot(sub(ma, c), ra) >= 0.0 { a1 } else { a0 };
            let fb = if dot(sub(mb, c), rb) >= 0.0 { b1 } else { b0 };
            for (dn, df) in [("rec", dir as fn(P) -> P), ("div", dird)] {
                let u = df(sub(fa, c));
                let w = df(sub(fb, c));
                // u, w from the lines' own directions
                let ua = if fa == a1 { df(ra) } else { df(mul(ra, -1.0)) };
                let wb = if fb == b1 { df(rb) } else { df(mul(rb, -1.0)) };
                for (un, uu, ww) in [("far", u, w), ("line", ua, wb)] {
