use std::collections::BTreeMap;
type P = [f64; 2];
fn sub(a: P, b: P) -> P {
    [a[0] - b[0], a[1] - b[1]]
}
fn dot(a: P, b: P) -> f64 {
    a[0] * b[0] + a[1] * b[1]
}
fn cross(a: P, b: P) -> f64 {
    a[0] * b[1] - a[1] * b[0]
}
fn hyp(a: P) -> f64 {
    a[0].hypot(a[1])
}
fn dir(a: P) -> P {
    let k = 1.0 / hyp(a);
    [a[0] * k, a[1] * k]
}
fn rot(a: P, t: f64) -> P {
    let (s, c) = t.sin_cos();
    [a[0] * c - a[1] * s, a[0] * s + a[1] * c]
}
fn rot2(a: P, t: f64) -> P {
    let s = t.sin();
    let c = t.cos();
    [a[0] * c - a[1] * s, a[0] * s + a[1] * c]
}
fn r3(x: f64) -> f64 {
    (x * 1000.0).round() / 1000.0
}

fn arc_c(a: P, b: P, deg: f64) -> (P, f64, f64) {
