fn golden(f: &dyn Fn(f64) -> f64, mut a: f64, mut b: f64, iters: usize, tol: f64, var: u8) -> f64 {
    let g = (5f64.sqrt() - 1.0) / 2.0;
    let mut it = 0;
    while it < iters && b - a > tol {
        let c = b - g * (b - a);
        let d = a + g * (b - a);
        let (fc, fd) = (f(c), f(d));
        match var {
            0 => {
                if fc < fd {
                    b = d
                } else {
                    a = c
                }
