    a[0] * b[0] + a[1] * b[1]
}

fn golden(f: &dyn Fn(f64) -> f64, mut a: f64, mut b: f64, iters: usize, tol: f64, var: u8) -> f64 {
    let g = (5f64.sqrt() - 1.0) / 2.0;
    let mut it = 0;
    while it < iters && b - a > tol {
        let c = b - g * (b - a);
        let d = a + g * (b - a);
        let (fc, fd) = (f(c), f(d));
        match var {
            0 => {
                if fc < fd {
                    b = d
                } else {
                    a = c
                }
            }
            1 => {
                if fc <= fd {
                    b = d
                } else {
                    a = c
                }
            }
            _ => {
                if fc < fd {
                    b = d
                } else if fc > fd {
                    a = c
                } else {
                    a = c;
                    b = d
                }
            }
        }
        it += 1;
    }
    (a + b) / 2.0
}

fn main() {
    let text = std::fs::read_to_string(std::env::args().nth(1).unwrap()).unwrap();
    let mut rows = Vec::new();
    for line in text.lines() {
        let v: Vec<f64> = line.split_whitespace().map(|x| x.parse().unwrap()).collect();
        if v.len() >= 8 {
            rows.push(([v[0], v[1]], [v[2], v[3]], [v[4], v[5]], [v[6], v[7]]));
        }
    }
    let mut score: BTreeMap<String, usize> = BTreeMap::new();
    for &(a, b, p, q) in &rows {
        let d = sub(b, a);
        let pt = |t: f64| add(a, mul(d, t));
        let f2 = |t: f64| {
            let e = sub(pt(t), p);
            dot(e, e)
        };
        let f1 = |t: f64| {
            let e = sub(pt(t), p);
            e[0].hypot(e[1])
        };
        let t0 = (dot(sub(p, a), d) / dot(d, d)).clamp(0.0, 1.0);
        for (fname, f) in [("d2", &f2 as &dyn Fn(f64) -> f64), ("d1", &f1)] {
            for var in 0..3u8 {
                for (bn, lo, hi) in [("01", 0.0, 1.0), ("t0+-1e-3", (t0 - 1e-3).max(0.0), (t0 + 1e-3).min(1.0)), ("t0+-1e-6", (t0 - 1e-6).max(0.0), (t0 + 1e-6).min(1.0))] {
                    for (tn, iters, tol) in [("it60", 60usize, 0.0), ("it100", 100, 0.0), ("tol1e-12", 1000, 1e-12), ("tol1e-15", 1000, 1e-15), ("tol1e-9", 1000, 1e-9)] {
                        let t = golden(f, lo, hi, iters, tol, var);
                        let k = format!("{} var{} {} {}", fname, var, bn, tn);
                        *score.entry(k).or_insert(0) += (pt(t) == q) as usize;
                    }
                }
            }
        }
    }
    let mut v: Vec<(String, usize)> = score.into_iter().collect();
    v.sort_by(|a, b| b.1.cmp(&a.1));
    for (k, s) in v.iter().take(10) {
        println!("{} / {} {}", s, rows.len(), k);
    }
}

